\n-- Exhistall: Exhibition booking requests\n-- Additive migration. Apply after 20260926_exhibition_halls.sql.\n-- This is an approval workflow only: it does not reserve, assign, publish or mark stalls as paid.\n\nDO $$\nBEGIN\n  CREATE TYPE public.exhibition_booking_status AS ENUM ('pending', 'contacted', 'approved', 'declined');\nEXCEPTION\n  WHEN duplicate_object THEN NULL;\nEND;\n$$;\n\nCREATE TABLE IF NOT EXISTS public.exhibition_booking_requests (\n  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),\n  exhibition_id uuid NOT NULL REFERENCES public.exhibitions(id) ON DELETE CASCADE,\n  requester_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE,\n  stall_id uuid REFERENCES public.stalls(id) ON DELETE SET NULL,\n  business_name text NOT NULL,\n  contact_name text NOT NULL,\n  email text NOT NULL,\n  phone text NOT NULL,\n  requested_package text NOT NULL DEFAULT 'standard',\n  message text NOT NULL DEFAULT '',\n  status public.exhibition_booking_status NOT NULL DEFAULT 'pending',\n  created_at timestamptz NOT NULL DEFAULT now(),\n  updated_at timestamptz NOT NULL DEFAULT now(),\n  CONSTRAINT exhibition_booking_requests_business_name_length CHECK (char_length(trim(business_name)) BETWEEN 2 AND 140),\n  CONSTRAINT exhibition_booking_requests_contact_name_length CHECK (char_length(trim(contact_name)) BETWEEN 2 AND 120),\n  CONSTRAINT exhibition_booking_requests_email_length CHECK (char_length(trim(email)) BETWEEN 3 AND 254),\n  CONSTRAINT exhibition_booking_requests_phone_length CHECK (char_length(trim(phone)) BETWEEN 3 AND 40),\n  CONSTRAINT exhibition_booking_requests_package_check CHECK (requested_package IN ('standard', 'featured', 'premium')),\n  CONSTRAINT exhibition_booking_requests_message_length CHECK (char_length(message) <= 2000)\n);\n\nDROP TRIGGER IF EXISTS exhibition_booking_requests_updated_at ON public.exhibition_booking_requests;\nCREATE TRIGGER exhibition_booking_requests_updated_at\nBEFORE UPDATE ON public.exhibition_booking_requests\nFOR EACH ROW EXECUTE FUNCTION public.set_updated_at();\n\nCREATE INDEX IF NOT EXISTS exhibition_booking_requests_admin_queue_idx\n  ON public.exhibition_booking_requests (status, created_at DESC);\nCREATE INDEX IF NOT EXISTS exhibition_booking_requests_requester_idx\n  ON public.exhibition_booking_requests (requester_id, created_at DESC);\nCREATE INDEX IF NOT EXISTS exhibition_booking_requests_exhibition_idx\n  ON public.exhibition_booking_requests (exhibition_id, created_at DESC);\n\n-- One open request per account per hall prevents accidental duplicates while\n-- allowing a declined applicant to apply again later if invited to do so.\nCREATE UNIQUE INDEX IF NOT EXISTS exhibition_booking_requests_one_open_per_user_idx\n  ON public.exhibition_booking_requests (exhibition_id, requester_id)\n  WHERE status IN ('pending', 'contacted', 'approved');\n\nALTER TABLE public.exhibition_booking_requests ENABLE ROW LEVEL SECURITY;\n\n-- Requesters can read only their own private contact details and status.\nDROP POLICY IF EXISTS "exhibition booking requests: requester reads own" ON public.exhibition_booking_requests;\nCREATE POLICY "exhibition booking requests: requester reads own"\nON public.exhibition_booking_requests FOR SELECT\nUSING (requester_id = auth.uid());\n\n-- An authenticated account may request a stall only for a live hall. If a\n-- stall is linked, it must belong to the requester. Status remains DB-default\n-- 'pending' because there is no requester UPDATE policy.\nDROP POLICY IF EXISTS "exhibition booking requests: authenticated create" ON public.exhibition_booking_requests;\nCREATE POLICY "exhibition booking requests: authenticated create"\nON public.exhibition_booking_requests FOR INSERT\nWITH CHECK (\n  requester_id = auth.uid()\n  AND status = 'pending'::public.exhibition_booking_status\n  AND EXISTS (\n    SELECT 1 FROM public.exhibitions hall\n    WHERE hall.id = exhibition_booking_requests.exhibition_id\n      AND hall.status = 'published'::public.exhibition_status\n      AND (hall.ends_at IS NULL OR hall.ends_at >= now())\n  )\n  AND (\n    stall_id IS NULL\n    OR EXISTS (\n      SELECT 1 FROM public.stalls owned_stall\n      WHERE owned_stall.id = exhibition_booking_requests.stall_id\n        AND owned_stall.owner_id = auth.uid()\n    )\n  )\n);\n\n-- Only administrators can review, change status, or delete a request.\nDROP POLICY IF EXISTS "exhibition booking requests: admin manages" ON public.exhibition_booking_requests;\nCREATE POLICY "exhibition booking requests: admin manages"\nON public.exhibition_booking_requests FOR ALL\nUSING (public.is_admin())\nWITH CHECK (public.is_admin());\n